// Snare Breeder spike: GENERATED by `npm run build` from snare-voice.js (the snare voice)
// and shared/breeder/dsp.js, engine.js and glue.js. Do not edit this file; edit those.
// ES5 only: Max 8's js object. Engine (makeBreeder) is pure and is unit tested in Node.

inlets = 1;
outlets = 1;
// outlet 0: "<slot> <velocity>" plays a slot (A, B, C, S1 to S4 or CUR) from a panel button.

// Breeder devices: maths shared by every drum voice. ES5 (Max 8's js object).
// Joined into each device's js by its build; see shared/breeder/README.md.

var BreederDsp = (function () {
  var MODULUS = 2147483647;
  var COMP_THRESHOLD = -24; // dB below the envelope's peak

  function toReal(param, v) {
    if (param.scale === "exp") return param.min * Math.pow(param.max / param.min, v);
    return param.min + (param.max - param.min) * v;
  }
  // Settings from 0 to 1, in PARAMS order, to real units by id.
  function realValues(params, values) {
    var out = {}, i;
    for (i = 0; i < params.length; i++) out[params[i].id] = toReal(params[i], values[i]);
    return out;
  }

  function tanh(x) {
    if (x > 20) return 1;
    if (x < -20) return -1;
    var e = Math.exp(2 * x);
    return (e - 1) / (e + 1);
  }

  // Compression of a one-shot: a static compressor on the envelope. Above the threshold, level
  // in dB is divided by the ratio; then make-up gain brings the peak back to full. The tail
  // comes up against the hit, as when a drum is compressed. It works on the envelope, not the
  // audio, so it never pumps, and it leaves the click alone (like a slow attack).
  function compress(level, amount) {
    if (level <= 0) return 0;
    var ratio = 1 + amount * 9, t = COMP_THRESHOLD;
    var shape = function (db) { return db > t ? t + (db - t) / ratio : db; };
    var db = 20 * Math.log(level) / Math.LN10;
    return Math.pow(10, (shape(db) - shape(0)) / 20);
  }

  // The patch plays line~ envelopes from breakpoint lists: a start value, then (target, time
  // in ms) pairs.

  // Pitch in Hz: from start down to end over `time`, falling as (1 - x)^power.
  function sweepPoints(start, end, time, power) {
    var n = 12, out = [start, 0], i, x;
    for (i = 1; i <= n; i++) {
      x = i / n;
      out.push(end + (start - end) * Math.pow(1 - x, power), time / n);
    }
    return out;
  }
  // A 1.5 ms rise, then an exponential fall to -60 dB over `length`, compressed, then silence.
  function decayPoints(peak, length, comp) {
    var n = 16, out = [0, 0, peak, 1.5], i;
    for (i = 1; i <= n; i++) out.push(peak * compress(Math.exp(-6.9 * i / n), comp), length / n);
    out.push(0, 5);
    return out;
  }
  // A click: starts at `level` and falls with a 4 ms time constant.
  function clickPoints(level) {
    var times = [2, 4, 8, 12, 20], out = [level, 0], last = 0, i;
    for (i = 0; i < times.length; i++) {
      out.push(level * Math.exp(-times[i] / 4), times[i] - last);
      last = times[i];
    }
    out.push(0, 10);
    return out;
  }
  function valueAt(points, ms) {
    var t = 0, i, v0 = points[0], v1, dt;
    for (i = 2; i < points.length; i += 2) {
      v1 = points[i]; dt = points[i + 1];
      if (ms <= t + dt) return dt > 0 ? v0 + (v1 - v0) * (ms - t) / dt : v1;
      t += dt; v0 = v1;
    }
    return v0;
  }
  // Steps through breakpoints sample by sample, faster than valueAt for long runs.
  function stepper(points, msPerSample) {
    var i = 2, t = 0, v0 = points[0], ms = 0;
    return function () {
      while (i < points.length && ms > t + points[i + 1]) { t += points[i + 1]; v0 = points[i]; i += 2; }
      var out = i >= points.length ? v0 : (points[i + 1] > 0 ? v0 + (points[i] - v0) * (ms - t) / points[i + 1] : points[i]);
      ms += msPerSample;
      return out;
    };
  }

  // White noise from -1 to 1, the same every run, so loudness is repeatable.
  function noise(seed) {
    var s = seed || 12345;
    return function () { s = (s * 16807) % MODULUS; return s / MODULUS * 2 - 1; };
  }

  // A state-variable filter for loudness simulations (the "TPT" form, stable up to Nyquist).
  // res 0 to 1, roughly as svf~'s resonance. Call f(x); then read f.low, f.band and f.high.
  function svf(freq, res, sr) {
    var g = Math.tan(Math.PI * Math.min(freq, sr * 0.45) / sr), k = 2 - 1.96 * Math.min(1, Math.max(0, res));
    var a1 = 1 / (1 + g * (g + k)), a2 = g * a1, a3 = g * a2, ic1 = 0, ic2 = 0;
    var f = function (x) {
      var v3 = x - ic2, v1 = a1 * ic1 + a2 * v3, v2 = ic2 + a2 * ic1 + a3 * v3;
      ic1 = 2 * v1 - ic1; ic2 = 2 * v2 - ic2;
      f.low = v2; f.band = v1; f.high = x - k * v1 - v2;
    };
    f.low = 0; f.band = 0; f.high = 0;
    return f;
  }

  // Ears hear 2 to 5 kHz as louder than the same level lower down, so a bright hit with plain
  // RMS matching comes out too loud. A rough stand-in for K-weighting (as in LUFS): a +4 dB
  // shelf above about 1.5 kHz. Returns a function from sample to weighted sample.
  function weighting(sr) {
    var a = 1 - Math.exp(-2 * Math.PI * 1500 / sr), low = 0;
    return function (x) { low += a * (x - low); return x + 0.58 * (x - low); };
  }

  // The loudest 50 ms window of RMS, and the peak, of a rendered hit.
  function measure(data, sr) {
    var win = Math.floor(sr * 0.05), hop = Math.floor(win / 4), best = 0, peak = 0, i, j, sum;
    for (i = 0; i < data.length; i++) if (Math.abs(data[i]) > peak) peak = Math.abs(data[i]);
    for (i = 0; i + win <= data.length; i += hop) {
      sum = 0;
      for (j = i; j < i + win; j++) sum += data[j] * data[j];
      if (sum > best) best = sum;
    }
    return { rms: Math.sqrt(best / win), peak: peak };
  }

  // The gain that brings a hit to the target loudness, without pushing its peak past the limit.
  function matchGain(level, target, peakLimit) {
    var gain = level.rms > 0 ? target / level.rms : 1;
    if (level.peak * gain > peakLimit) gain = peakLimit / level.peak;
    return gain;
  }

  function hz(v) { return v >= 1000 ? (v / 1000).toFixed(1) + " kHz" : v.toFixed(0) + " Hz"; }

  return {
    MODULUS: MODULUS, toReal: toReal, realValues: realValues, tanh: tanh, compress: compress,
    sweepPoints: sweepPoints, decayPoints: decayPoints, clickPoints: clickPoints,
    valueAt: valueAt, stepper: stepper, noise: noise, svf: svf, weighting: weighting,
    measure: measure, matchGain: matchGain, hz: hz
  };
})();

// Breeder devices: the breeding engine, the same for every drum. ES5 (Max 8's js object).
// Joined into each device's js by its build; see shared/breeder/README.md.
//
// makeBreeder(voice) takes a drum voice (its PARAMS, and functions such as voice and describe)
// and returns one object with the breeding functions and the voice's functions together. Pure:
// every function returns a new state and leaves the old one alone.

function makeBreeder(drum) {
  var PARAMS = drum.PARAMS;
  var START_STEP = 0.25, MIN_STEP = 0.02, MAX_STEP = 0.5, SHRINK = 0.6;
  var MODULUS = BreederDsp.MODULUS;

  function clone(x) { return JSON.parse(JSON.stringify(x)); }
  function clampStep(v) { return Math.min(MAX_STEP, Math.max(MIN_STEP, v)); }

  // Park-Miller generator: the product stays below 2^53, so plain doubles are exact.
  function rand(s) { s.seed = (s.seed * 16807) % MODULUS; return (s.seed - 1) / (MODULUS - 1); }
  function gauss(s) {
    var u1 = Math.max(rand(s), 1e-9), u2 = rand(s);
    return Math.sqrt(-2 * Math.log(u1)) * Math.cos(2 * Math.PI * u2);
  }
  // Reflect off the ends, so values near an edge are not piled up on it.
  function fold(v) {
    if (v < 0) v = -v;
    if (v > 1) v = 2 - v;
    return Math.min(1, Math.max(0, v));
  }

  function randomValues(s) {
    var out = [], i;
    for (i = 0; i < PARAMS.length; i++) out.push(rand(s));
    return out;
  }
  function mutate(s, values) {
    var out = [], i;
    for (i = 0; i < PARAMS.length; i++) {
      out.push(s.locks[PARAMS[i].id] ? values[i] : fold(values[i] + gauss(s) * s.step));
    }
    return out;
  }
  function candidate(s, values, favourite) {
    var c = { id: s.nextId, values: values, favourite: favourite };
    s.nextId += 1;
    return c;
  }
  function shuffle(s, list) {
    var i, j, t;
    for (i = list.length - 1; i > 0; i--) {
      j = Math.floor(rand(s) * (i + 1));
      t = list[i]; list[i] = list[j]; list[j] = t;
    }
    return list;
  }
  function breed(s, favValues) {
    var list = [candidate(s, favValues, true), candidate(s, mutate(s, favValues), false), candidate(s, mutate(s, favValues), false)];
    return s.shuffle ? shuffle(s, list) : list;
  }
  function snapshot(state) { var c = clone(state); c.past = []; return c; }
  function favourite(state) {
    var i;
    for (i = 0; i < state.candidates.length; i++) if (state.candidates[i].favourite) return state.candidates[i];
    return null;
  }

  function create(seed, options) {
    var o = options || {};
    var s = {
      seed: (Math.abs(Math.floor(seed)) % (MODULUS - 1)) + 1,
      round: 1, step: START_STEP, locks: o.locks ? clone(o.locks) : {}, shuffle: o.shuffle !== false,
      nextId: 1, candidates: [], past: [], picks: []
    };
    s.candidates = [candidate(s, randomValues(s), false), candidate(s, randomValues(s), false)];
    return s;
  }

  // The user prefers slot `index`. It becomes the favourite and two variations are bred from it.
  // Choosing the favourite again means "close", so the variations get smaller.
  function choose(state, index) {
    var picked = state.candidates[index], s;
    if (!picked) return state;
    s = clone(state);
    s.past.push(snapshot(state));
    if (picked.favourite) s.step = clampStep(s.step * SHRINK);
    s.picks.push({ round: s.round, slot: index, favourite: picked.favourite, step: s.step });
    s.round += 1;
    s.candidates = breed(s, picked.values.slice());
    return s;
  }
  // The Variation slider: a new size, and the two variations bred again at that size.
  // Not added to Back's history, so dragging the slider does not fill it.
  function setStep(state, step) {
    var fav = favourite(state), s = clone(state);
    s.step = clampStep(step);
    if (fav) s.candidates = breed(s, fav.values.slice());
    return s;
  }
  function back(state) {
    var s;
    if (!state.past.length) return state;
    s = clone(state.past[state.past.length - 1]);
    s.past = clone(state.past.slice(0, -1));
    return s;
  }
  // Start again from round 1: new drums, the starting variation size, and no locks.
  function reset(state) {
    var r = { seed: state.seed };
    rand(r);
    return create(r.seed, { shuffle: state.shuffle });
  }
  function setLock(state, id, on) {
    var s = clone(state);
    s.locks[id] = !!on;
    return s;
  }
  function setShuffle(state, on) { var s = clone(state); s.shuffle = !!on; return s; }
  // Start a new search with `values` as the favourite.
  function breedFrom(state, values) {
    var s = clone(state);
    s.past.push(snapshot(state));
    s.step = clampStep(START_STEP / 2);
    s.round += 1;
    s.candidates = breed(s, values.slice());
    return s;
  }

  var engine = {
    PARAMS: PARAMS, START_STEP: START_STEP, MIN_STEP: MIN_STEP, MAX_STEP: MAX_STEP,
    create: create, choose: choose, setStep: setStep, back: back, reset: reset,
    setLock: setLock, setShuffle: setShuffle, breedFrom: breedFrom, favourite: favourite,
    toReal: BreederDsp.toReal,
    realValues: function (values) { return BreederDsp.realValues(PARAMS, values); },
    compress: BreederDsp.compress, valueAt: BreederDsp.valueAt
  };
  var key;
  for (key in drum) if (drum.hasOwnProperty(key) && !engine.hasOwnProperty(key)) engine[key] = drum[key];
  return engine;
}

// Snare Breeder spike: the snare voice. ES5 (Max 8's js object): var, function, no arrows, no
// Math.tanh or Math.imul. `npm run build` joins this with the shared breeding engine and Max
// glue (shared/breeder/) into snare-breeder.js, which is what the device loads.
//
// A snare is two sounds at once: the drum skin (two swept sines, a fundamental and one
// overtone) and the snare wires (band-passed noise). Bursts restarts the wires a few times
// before the tail, which turns a snare into a clap. Snap is a short, bright crack on top.
//
// Throwaway spike: see README.md in this folder for what it is testing.

var Drum = (function () {
  var PARAMS = [
    { id: "pitch", name: "Pitch", short: "Pitch", min: 120, max: 400, scale: "exp" },
    { id: "sweep", name: "Sweep", short: "Sweep", min: 0, max: 24, scale: "lin" },
    { id: "sweepTime", name: "Sweep time", short: "Sweep T", min: 5, max: 80, scale: "exp" },
    { id: "ratio", name: "Overtone ratio", short: "Ratio", min: 1.3, max: 2.4, scale: "lin" },
    { id: "ring", name: "Overtone level", short: "Ring", min: 0, max: 1, scale: "lin" },
    { id: "bodyDecay", name: "Body decay", short: "Body D", min: 30, max: 500, scale: "exp" },
    { id: "balance", name: "Body to wires", short: "Balance", min: 0, max: 1, scale: "lin" },
    { id: "wiresDecay", name: "Wires decay", short: "Wires D", min: 40, max: 800, scale: "exp" },
    { id: "wiresTone", name: "Wires tone", short: "Wires T", min: 800, max: 10000, scale: "exp" },
    { id: "width", name: "Wires width", short: "Width", min: 0, max: 1, scale: "lin" },
    { id: "bursts", name: "Bursts", short: "Bursts", min: 0, max: 1, scale: "lin" },
    { id: "spread", name: "Burst spread", short: "Spread", min: 4, max: 20, scale: "exp" },
    { id: "snap", name: "Snap", short: "Snap", min: 0, max: 1, scale: "lin" },
    { id: "compression", name: "Compression", short: "Comp", min: 0, max: 1, scale: "lin" },
    { id: "saturation", name: "Saturation", short: "Sat", min: 0, max: 1, scale: "lin" },
    { id: "tone", name: "Tone", short: "Tone", min: 1000, max: 16000, scale: "exp" }
  ];
  // What the patch stores per slot, in the order its trigger fires them: settings first.
  var PARTS = ["statics", "freq", "wires", "amp", "snap"];
  var TARGET_RMS = 0.2, RAW_GAIN = 0.5, PEAK_LIMIT = 0.95;
  var SNAP_FREQ = 2500, SNAP_RES = 0.2; // fixed in the patch: svf~ 2500 0.2, high-pass out
  var D = BreederDsp, tanh = D.tanh;

  function real(values) { return D.realValues(PARAMS, values); }

  // Half of all snares have one burst (a plain snare); the rest have 2, 3 or 4 (towards a clap).
  function burstCount(v) { return v < 0.5 ? 1 : 2 + Math.min(2, Math.floor((v - 0.5) * 6)); }
  // Equal-power balance: 0 is all body, 1 all wires.
  function bodyLevel(p) { return Math.cos(p.balance * Math.PI / 2); }
  function wiresLevel(p) { return Math.sin(p.balance * Math.PI / 2); }
  // svf~ resonance for the wires: wide (0) to narrow and ringing (0.8).
  function wiresRes(p) { return 0.8 * (1 - p.width); }

  function freqPoints(p) {
    var start = Math.min(p.pitch * Math.pow(2, p.sweep / 12), 16000);
    return D.sweepPoints(start, p.pitch, p.sweepTime, 3);
  }
  function ampPoints(p) { return D.decayPoints(bodyLevel(p), p.bodyDecay, p.compression); }
  // Each early burst jumps up and falls away over Spread, then the last one rings out.
  function wiresPoints(p) {
    var n = burstCount(p.bursts), peak = wiresLevel(p), tail = D.decayPoints(peak, p.wiresDecay, p.compression);
    var out = [0, 0], i;
    if (n === 1) return tail;
    for (i = 1; i < n; i++) out.push(peak, 0.5, peak * 0.12, p.spread - 0.5);
    return out.concat(tail.slice(2));
  }
  function snapPoints(p) { return D.clickPoints(p.snap * 1.5); }

  // A rough simulation of the patch's voice, to measure loudness: the loudest 50 ms window of
  // weighted RMS in the first 300 ms. Close enough to level-match snares; not sample exact.
  function loudness(p) {
    var sr = 22050, len = Math.floor(sr * 0.3), msPer = 1000 / sr;
    var f = D.stepper(freqPoints(p), msPer), a = D.stepper(ampPoints(p), msPer);
    var w = D.stepper(wiresPoints(p), msPer), sn = D.stepper(snapPoints(p), msPer);
    var k = 1 + p.saturation * 12, outGain = 1 / tanh(k), white = D.noise(12345);
    var wires = D.svf(p.wiresTone, wiresRes(p), sr), snap = D.svf(SNAP_FREQ, SNAP_RES, sr);
    var weigh = D.weighting(sr), lp = 1 - Math.exp(-2 * Math.PI * Math.min(p.tone, sr / 2.2) / sr);
    var ph1 = 0.75, ph2 = 0.75, y = 0, heard = [], raw = [], i, n, x, hz;
    for (i = 0; i < len; i++) {
      hz = f();
      ph1 += hz / sr;
      ph2 += hz * p.ratio / sr;
      n = white();
      wires(n);
      snap(n);
      x = (Math.cos(2 * Math.PI * ph1) + p.ring * Math.cos(2 * Math.PI * ph2)) * a() + wires.band * w() + snap.high * sn();
      x = tanh(k * x) * outGain;
      y += lp * (x - y);
      raw.push(y);
      heard.push(weigh(y));
    }
    return { rms: D.measure(heard, sr).rms, peak: D.measure(raw, sr).peak };
  }

  // Everything the patch needs to play one snare. match: level-match it to the others.
  function voice(values, match) {
    var p = real(values), k = 1 + p.saturation * 12;
    var gain = match ? D.matchGain(loudness(p), TARGET_RMS, PEAK_LIMIT) : RAW_GAIN;
    return {
      freq: freqPoints(p), amp: ampPoints(p), wires: wiresPoints(p), snap: snapPoints(p),
      // In the order the patch unpacks them: overtone ratio and level, wires tone and
      // resonance, saturation in and out, tone, output gain.
      statics: [p.ratio, p.ring, p.wiresTone, wiresRes(p), k, 1 / tanh(k), p.tone, gain]
    };
  }

  function describe(values) {
    var p = real(values), hz = D.hz, n = burstCount(p.bursts);
    return hz(p.pitch) + ", ring " + p.ring.toFixed(2) + " at " + p.ratio.toFixed(2) + "x, body " +
      p.bodyDecay.toFixed(0) + " ms, wires " + p.wiresDecay.toFixed(0) + " ms at " + hz(p.wiresTone) +
      ", balance " + p.balance.toFixed(2) + ", " + n + (n === 1 ? " burst" : " bursts") +
      ", snap " + p.snap.toFixed(2) + ", comp " + p.compression.toFixed(2) + ", sat " + p.saturation.toFixed(2) +
      ", tone " + hz(p.tone);
  }
  // A short name for a saved slot.
  function label(values) {
    var p = real(values);
    return D.hz(p.pitch) + (burstCount(p.bursts) >= 3 ? " clap" : " snare");
  }

  return {
    NOUN: "snare", PARAMS: PARAMS, PARTS: PARTS, SNAP_FREQ: SNAP_FREQ, SNAP_RES: SNAP_RES,
    voice: voice, loudness: loudness, describe: describe, label: label, burstCount: burstCount
  };
})();

var Engine = makeBreeder(Drum);
if (typeof module !== "undefined" && module.exports) module.exports = Engine;

// Breeder devices: the Max glue, the same for every drum. ES5 (Max 8's js object).
// Joined into each device's js by its build, after `var Engine = makeBreeder(...)`.
//
// Buttons may send 1 then 0, or a bang (as in TAP), so every press handler ignores a 0.
// Panel objects are found by their scripting names (varname) and set with "set", so nothing
// feeds back into this file. Each slot's drum lives in message boxes in the patch,
// <slot>_<part> for each of Engine.PARTS, so a MIDI note plays it without waiting for this
// file. Saved drums live in hidden stored-only numboxes, so they save with the set:
// save_<n>_<param> (0 to 1) and save_<n>_on.

var SLOTS = ["A", "B", "C"];
var SAVED = 4;
var PLAY_KEYS = ["C3", "D3", "E3"];
var SAVE_KEYS = ["F3", "G3", "A3", "B3"];
var NOUN = Engine.NOUN;
var state = null;
var heard = "A"; // the slot MIDI notes outside the mapped keys play: A, B, C or S1 to S4
var matchOn = true, showFav = false, shuffleOn = true;
var saved = [null, null, null, null]; // normalised values, or null when empty
var locks = {};
var voiceCache = {};

function named(name) { return this.patcher ? this.patcher.getnamed(name) : null; }
function show(name, text) { var o = named(name); if (o) o.message("set", text); }
function setBox(name, list) { var o = named(name); if (o) o.message.apply(o, ["set"].concat(list)); }
function pressed(v) { return v === undefined || v !== 0; }

function valuesOf(slot) {
  if (slot.charAt(0) === "S") return saved[Number(slot.charAt(1)) - 1];
  var c = state && state.candidates[SLOTS.indexOf(slot)];
  return c ? c.values : null;
}

function voiceOf(values) {
  var key = values.join(",") + (matchOn ? "m" : "r");
  if (!voiceCache[key]) voiceCache[key] = Engine.voice(values, matchOn);
  return voiceCache[key];
}

// Fill one slot's message boxes: <slot>_statics and one per envelope.
function fill(slot, values) {
  var v = voiceOf(values), i;
  for (i = 0; i < Engine.PARTS.length; i++) setBox(slot + "_" + Engine.PARTS[i], v[Engine.PARTS[i]]);
}

function render() {
  if (!state) return;
  var i, c, values;
  for (i = 0; i < 3; i++) {
    c = state.candidates[i];
    if (c) fill(SLOTS[i], c.values);
    show("fav_" + i, PLAY_KEYS[i] + (!c ? "  (none this round)" : (showFav && c.favourite ? "  favourite" : "")));
  }
  for (i = 0; i < SAVED; i++) {
    if (saved[i]) fill("S" + (i + 1), saved[i]);
    show("saved_" + i, SAVE_KEYS[i] + (saved[i] ? "  " + Engine.label(saved[i]) : "  empty"));
  }
  values = valuesOf(heard);
  if (!values) { heard = "A"; values = valuesOf(heard); }
  fill("CUR", values);
  show("status", "Round " + state.round + "  |  choices " + state.picks.length + "  |  variation " +
    state.step.toFixed(2) + "  |  hearing " + (heard.charAt(0) === "S" ? "saved " + heard.charAt(1) : heard));
  show("detail", Engine.describe(values));
  var slider = named("variation");
  if (slider) slider.message("set", state.step);
}

function init() {
  var i, j, o, values, on;
  for (i = 0; i < Engine.PARAMS.length; i++) {
    o = named("lock_" + i);
    if (o) locks[Engine.PARAMS[i].id] = o.getvalueof() === 1;
  }
  for (i = 0; i < SAVED; i++) {
    o = named("save_" + (i + 1) + "_on");
    on = o && o.getvalueof() === 1;
    if (!on) { saved[i] = null; continue; }
    values = [];
    for (j = 0; j < Engine.PARAMS.length; j++) {
      o = named("save_" + (i + 1) + "_" + j);
      values.push(o ? Number(o.getvalueof()) : 0.5);
    }
    saved[i] = values;
  }
  o = named("match"); if (o) matchOn = o.getvalueof() === 1;
  o = named("shuffle"); if (o) shuffleOn = o.getvalueof() === 1;
  o = named("showfav"); if (o) showFav = o.getvalueof() === 1;
  state = Engine.create(new Date().getTime() % 100000, { shuffle: shuffleOn, locks: locks });
  heard = "A";
  render();
}

// Hear a slot from the panel: it becomes the drum other notes play, and it plays now.
function play(slot) {
  if (!state || !valuesOf(slot)) { if (slot.charAt(0) === "S") show("status", "Saved " + slot.charAt(1) + " is empty."); return; }
  heard = slot;
  render();
  outlet(0, slot, 127);
}
function hear_a(v) { if (pressed(v)) play("A"); }
function hear_b(v) { if (pressed(v)) play("B"); }
function hear_c(v) { if (pressed(v)) play("C"); }
function play_1(v) { if (pressed(v)) play("S1"); }
function play_2(v) { if (pressed(v)) play("S2"); }
function play_3(v) { if (pressed(v)) play("S3"); }
function play_4(v) { if (pressed(v)) play("S4"); }

// A mapped key was played (C3 to E3, F3 to B3). The patch already played it; just remember it.
function heard_slot(slot) {
  if (!state || heard === slot || !valuesOf(slot)) return;
  heard = slot;
  render();
}

function choose(index, v) {
  if (!pressed(v) || !state || !state.candidates[index]) return;
  state = Engine.choose(state, index);
  heard = "A";
  render();
}
function choose_a(v) { choose(0, v); }
function choose_b(v) { choose(1, v); }
function choose_c(v) { choose(2, v); }

// Save the drum last heard into saved slot n (1 to 4), and into the set.
function save(n, v) {
  if (!pressed(v) || !state) return;
  var values = valuesOf(heard), j, o;
  if (!values) return;
  saved[n - 1] = values.slice();
  for (j = 0; j < values.length; j++) {
    o = named("save_" + n + "_" + j);
    if (o) o.message("set", values[j]);
  }
  o = named("save_" + n + "_on");
  if (o) o.message("set", 1);
  render();
  show("status", "Saved to " + n + " (" + SAVE_KEYS[n - 1] + "), after " + state.picks.length + " choices.");
}
function save_1(v) { save(1, v); }
function save_2(v) { save(2, v); }
function save_3(v) { save(3, v); }
function save_4(v) { save(4, v); }

function back(v) { if (pressed(v) && state) { state = Engine.back(state); heard = "A"; render(); } }
function reset(v) {
  if (!pressed(v) || !state) return;
  var i, o;
  for (i = 0; i < Engine.PARAMS.length; i++) {
    o = named("lock_" + i);
    if (o) o.message("set", 0);
  }
  locks = {};
  state = Engine.reset(state);
  heard = "A";
  render();
  show("status", "Reset: round 1, variation " + state.step.toFixed(2) + ", no locks. Saved " + NOUN + "s are kept.");
}
function breed_from_heard(v) {
  if (!pressed(v) || !state) return;
  state = Engine.breedFrom(state, valuesOf(heard));
  heard = "A";
  render();
}

// From the panel: Variation slider, locks and toggles.
function variation(value) { if (state) { state = Engine.setStep(state, value); render(); } }
function lock(index, value) {
  var id = Engine.PARAMS[index].id;
  locks[id] = value === 1;
  if (state) state = Engine.setLock(state, id, locks[id]);
}
function match(v) { matchOn = v === 1; render(); }
function shuffle(v) { shuffleOn = v === 1; if (state) state = Engine.setShuffle(state, shuffleOn); }
function showfav(v) { showFav = v === 1; render(); }
